    public static let variants = groups.flatMap { $0 }
    static let ids = Dictionary(uniqueKeysWithValues: variants.enumerated().map { ($0.element, $0.offset) })
    private struct Node {
        var next: [UInt16: Int] = [:]
        var id: Int?
    }
    // 286表現の大きい選択の正規表現を候補ごとに走らせず、共通の語頭を一度だけ準備する。
    private static let trie: [Node] = {
        var nodes = [Node()]
        for (id, term) in variants.enumerated() {
            var node = 0
            for unit in term.utf16 {
                if let next = nodes[node].next[unit] { node = next }
                else {
                    let next = nodes.count; nodes.append(Node()); nodes[node].next[unit] = next; node = next
                }
            }
            nodes[node].id = id
        }
        return nodes
    }()
    public static let groupIDs: [[Int]] = groups.map { $0.map { ids[$0]! } }

    static func matches(_ text: String, words: PersonalOrthography.Words, boundaries supplied: (() -> Set<String.Index>)? = nil) -> [(range: Range<String.Index>, id: Int)] {
        let units = Array(text.utf16)
        var found: [(range: NSRange, id: Int)] = [], start = 0
        while start < units.count {
            var node = 0, cursor = start, longest: (end: Int, id: Int)?
            while cursor < units.count, let next = trie[node].next[units[cursor]] {
                node = next; cursor += 1
                if let id = trie[node].id { longest = (cursor, id) }
            }
            if let longest {
                found.append((NSRange(location: start, length: longest.end - start), longest.id)); start = longest.end
            } else { start += 1 }
        }
        guard !found.isEmpty else { return [] }
        let boundaries = supplied?() ?? words.boundaries(text)
        return found.compactMap {
            guard let range = Range($0.range, in: text), boundaries.contains(range.lowerBound), boundaries.contains(range.upperBound) else { return nil }
            return (range, $0.id)
        }
    }
    static func replacements(usage: [Int: Int]) -> [Int: Int] {
        var replacements: [Int: Int] = [:]
        for group in groupIDs {
            guard let target = group.filter({ usage[$0, default: 0] >= 2 }).max(by: {
                (usage[$0, default: 0], -$0) < (usage[$1, default: 0], -$1)
            }) else { continue }
            for source in group where usage[source, default: 0] == 0 { replacements[source] = target }
        }
        return replacements
    }
    public static func containsUnused(_ text: String, usage: [Int: Int]) -> Bool {
        matches(text, words: PersonalOrthography.observationWords).contains { usage[$0.id, default: 0] == 0 }
    }
    public static func protectedTerms(usage: [Int: Int]) -> [String] {
        usage.keys.sorted().filter { variants.indices.contains($0) && usage[$0, default: 0] >= 2 }.map { variants[$0] }
    }
